import csv

# Test RFC 4180 compliance - check that fields with commas are quoted
with open('outputs/t05_clean_stops.csv', 'r', newline='') as f:
    content = f.read()

# Check for any unquoted commas in non-quoted fields
lines = content.split('\n')
for i, line in enumerate(lines):
    # Skip header
    if i == 0:
        continue
    # Parse using csv module
    try:
        reader = csv.reader([line])
        rows = list(reader)
        if len(rows) == 0:
            continue
        for j, row in enumerate(rows):
            # Check if any field contains comma but isn't quoted
            for k, field in enumerate(row):
                if ',' in field:
                    # Should be quoted if it contains comma
                    # The csv module handles this, so we just verify parsing works
                    pass
    except Exception as e:
        print(f'Line {i}: Parse error: {e}')

print('CSV parsing successful')
