import json

# Verify report structure
with open('outputs/t05_gtfs_cleaning_report.json', 'r') as f:
    report = json.load(f)

required_fields = ['invalid_coordinates_removed', 'duplicate_stops_removed', 
                   'missing_stop_names_filled', 'n_clean_stops', 'n_clean_stop_times']

for field in required_fields:
    if field not in report:
        print(f'Missing field: {field}')
    elif not isinstance(report[field], int):
        print(f'Field {field} is not an integer: {type(report[field])}')
    else:
        print(f'{field}: {report[field]} (integer)')

print('Report validation complete')
